1	//! SPSC ring v1: the seam-word protocol, per the design doc's
2	//! "SPSC v1: seam-word ring" section.
3	//!
4	//! - Same region shape as v0 (a four-line [`Header`], then
5	//!   slots) plus a per-slot sequence array between them, as
6	//!   the MPSC ring has: `seq[pos]` publishes each slot on its
7	//!   own, so neither side ever reads the other side's index
8	//!   line. v0 moved ~10 cache lines per cross-core round trip
9	//!   against the MPSC ring's ~6.7 because each side polled the
10	//!   other's index; here the producer polls the slot's seq and
11	//!   the consumer the same word, and the index lines are each
12	//!   side's private resume state.
13	//! - MPSC's protocol minus the claim CAS: one producer owns
14	//!   `producer_idx`, so it claims a slot by loading the seq,
15	//!   never by compare-exchange. Load/store only, so the v0
16	//!   atomic floor holds (thumbv6m keeps working).
17	//! - Own magic and layout version: a region is one kind or
18	//!   the other, and cross-attaching fails toward
19	//!   [`Error::BadMagic`].
20	//! - `capacity` may be any power of two down to 1: the state
21	//!   lives in the seq, not in an index distance, so no
22	//!   sacrificial slot. Committed is `pos + M + 1`, not
23	//!   Vyukov's `pos + 1`, which at `M = 1` would equal the
24	//!   released value `pos + M` and let the producer overwrite
25	//!   an unread slot.
26	
27	use core::marker::PhantomData;
28	use core::mem::size_of;
29	use core::sync::atomic::{AtomicU32, Ordering};
30	
31	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, USER_WORDS};
32	
33	mod consumer;
34	mod producer;
35	
36	pub use consumer::{Consumer, ReadSlot};
37	pub use producer::{Producer, WriteSlot};
38	
39	/// Layout marker written by [`Ring::init`]; distinct from the
40	/// v0 and MPSC magics so cross-kind attach fails toward
41	/// [`Error::BadMagic`].
42	const MAGIC: u32 = 0x5A43_5232; // "ZCR2"
43	
44	/// Bumped on any change to the v1 region layout; independent
45	/// of the v0 layout version.
46	const LAYOUT_VERSION: u32 = 1;
47	
48	/// Capacity bound: `2^30`, as the MPSC ring, so the seq
49	/// arithmetic keeps the same headroom and a v1 region can be
50	/// read with the MPSC ring's numbers in mind.
51	const MAX_CAPACITY: u32 = 1 << 30;
52	
53	/// Control block at offset 0 of a v1 region — the v0
54	/// [`Header`](crate::spsc::v0::Header)'s four-line shape, its own type.
55	///
56	/// - line 0: geometry, written by [`Ring::init`] with `magic`
57	///   last (`Release`), read-only thereafter.
58	/// - line 1: `producer_idx`, the producer's resume state:
59	///   written and read only by the producer, never by the
60	///   consumer's hot path.
61	/// - line 2: `consumer_idx`, the consumer's resume state,
62	///   likewise private to it.
63	/// - line 3: `user`, app-owned scratch — same contract as
64	///   v0's user line.
65	/// - Every field is atomic: the region may be mapped by a
66	///   peer at any time.
67	#[repr(C)]
68	pub struct Header {
69	    /// Layout marker ([`MAGIC`]); stored last by init
70	    /// (`Release`), loaded first by attach (`Acquire`).
71	    magic: AtomicU32,
72	    /// Layout version ([`LAYOUT_VERSION`]).
73	    layout_version: AtomicU32,
74	    /// Slot size N in bytes — a [`CACHE_LINE_SIZE`] multiple.
75	    slot_size: AtomicU32,
76	    /// Slot count M — a power of two `<= 2^30`.
77	    capacity: AtomicU32,
78	    /// [`CACHE_LINE_SIZE`] this region was built with.
79	    cache_line_size: AtomicU32,
80	    /// Free-running count of messages committed; producer
81	    /// resume state, not read by the consumer.
82	    producer_idx: CacheAligned<AtomicU32>,
83	    /// Free-running count of messages released; consumer
84	    /// resume state, not read by the producer.
85	    consumer_idx: CacheAligned<AtomicU32>,
86	    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
87	    /// init, then never touched by the crate.
88	    user: CacheAligned<[AtomicU32; USER_WORDS]>,
89	}
90	
91	const _: () = assert!(size_of::<Header>() == 4 * CACHE_LINE_SIZE);
92	
93	/// A validated view over a v1 ring region; split into the two
94	/// endpoint handles with [`Ring::split`].
95	///
96	/// - Geometry is snapshotted out of the header at init/attach,
97	///   as v0 does: per-op paths never re-read fields a peer
98	///   could scribble on.
99	/// - Region layout: [`Header`], the seq array (`M ×
100	///   AtomicU32`, padded up to a cache line), then M slots of N
101	///   bytes.
102	pub struct Ring<'a> {
103	    /// The region's control block.
104	    header: &'a Header,
105	    /// Base of the per-slot sequence array.
106	    seqs: *const AtomicU32,
107	    /// Base of the slot array.
108	    slots: *mut u8,
109	    /// Snapshot of `header.slot_size`.
110	    slot_size: u32,
111	    /// Snapshot of `header.capacity`.
112	    capacity: u32,
113	    /// Slot-position mask (`capacity - 1`).
114	    mask: u32,
115	    _region: PhantomData<&'a [u8]>,
116	}
117	
118	impl<'a> Ring<'a> {
119	    /// Initialize a fresh region and return the ring over it.
120	    ///
121	    /// - `slot_size` — N bytes per slot, a [`CACHE_LINE_SIZE`]
122	    ///   multiple.
123	    /// - `capacity` — M slots, a power of two `<= 2^30`, 1
124	    ///   included.
125	    /// - The region must be [`CACHE_LINE_SIZE`]-aligned and at
126	    ///   least [`region_size`] bytes.
127	    pub fn init(region: &'a mut [u8], slot_size: u32, capacity: u32) -> Result<Self, Error> {
128	        validate_geometry(slot_size, capacity)?;
129	        let len = region.len();
130	        // Taken exactly once, as v0 does: a second
131	        // `as_mut_ptr()` would retag the slice and invalidate
132	        // `header` under Stacked Borrows.
133	        let base = region.as_mut_ptr();
134	        let header = header_ptr(base, len)?;
135	        if (len as u64) < region_size(slot_size, capacity) {
136	            return Err(Error::TooSmall);
137	        }
138	        // SAFETY: alignment + room for the Header checked by
139	        // header_ptr; region is exclusively borrowed for 'a;
140	        // any byte pattern is a valid Header (all-atomic
141	        // fields, plain-byte padding).
142	        let header = unsafe { &*header };
143	        header
144	            .layout_version
145	            .store(LAYOUT_VERSION, Ordering::Relaxed);
146	        header.slot_size.store(slot_size, Ordering::Relaxed);
147	        header.capacity.store(capacity, Ordering::Relaxed);
148	        header
149	            .cache_line_size
150	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
151	        header.producer_idx.store(0, Ordering::Relaxed);
152	        header.consumer_idx.store(0, Ordering::Relaxed);
153	        for word in header.user.iter() {
154	            word.store(0, Ordering::Relaxed);
155	        }
156	        // SAFETY: in bounds — region.len() >= region_size.
157	        let seqs = unsafe { base.add(size_of::<Header>()) } as *const AtomicU32;
158	        // `seq[i] = i`: every slot claimable for lap 0.
159	        for i in 0..capacity {
160	            // SAFETY: i < capacity, inside the seq array.
161	            unsafe { &*seqs.byte_add(i as usize * SEQ_STRIDE) }.store(i, Ordering::Relaxed);
162	        }
163	        // Published last: a peer that pre-mapped the region must
164	        // never observe MAGIC before the geometry and seqs it
165	        // relies on.
166	        header.magic.store(MAGIC, Ordering::Release);
167	        // SAFETY: in bounds — region.len() >= region_size.
168	        let slots = unsafe { base.add(slots_offset(capacity)) };
169	        Ok(Ring {
170	            header,
171	            seqs,
172	            slots,
173	            slot_size,
174	            capacity,
175	            mask: capacity - 1,
176	            _region: PhantomData,
177	        })
178	    }
179	
180	    /// Attach to a region another process (or an earlier call)
181	    /// already initialized, validating its header.
182	    ///
183	    /// # Safety
184	    ///
185	    /// - `region` points to `len` bytes of memory that outlive
186	    ///   `'a`, genuinely shared and writable (e.g. a
187	    ///   `MAP_SHARED` mapping).
188	    /// - No other producer attaches if this side will produce;
189	    ///   likewise for the consumer side (SPSC contract).
190	    pub unsafe fn attach(region: *mut u8, len: usize) -> Result<Self, Error> {
191	        let header = header_ptr(region, len)?;
192	        // SAFETY: alignment + room for the Header checked by
193	        // header_ptr; caller guarantees the memory is live and
194	        // shared.
195	        let header = unsafe { &*header };
196	        // Acquire pairs with init's Release store of magic.
197	        if header.magic.load(Ordering::Acquire) != MAGIC {
198	            return Err(Error::BadMagic);
199	        }
200	        if header.layout_version.load(Ordering::Relaxed) != LAYOUT_VERSION {
201	            return Err(Error::BadLayoutVersion);
202	        }
203	        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
204	            return Err(Error::BadCacheLine);
205	        }
206	        // Snapshot geometry once; per-op paths never re-read it.
207	        let slot_size = header.slot_size.load(Ordering::Relaxed);
208	        let capacity = header.capacity.load(Ordering::Relaxed);
209	        validate_geometry(slot_size, capacity)?;
210	        if (len as u64) < region_size(slot_size, capacity) {
211	            return Err(Error::TooSmall);
212	        }
213	        // SAFETY: in bounds — len >= region_size.
214	        let seqs = unsafe { region.add(size_of::<Header>()) } as *const AtomicU32;
215	        // SAFETY: as above.
216	        let slots = unsafe { region.add(slots_offset(capacity)) };
217	        Ok(Ring {
218	            header,
219	            seqs,
220	            slots,
221	            slot_size,
222	            capacity,
223	            mask: capacity - 1,
224	            _region: PhantomData,
225	        })
226	    }
227	
228	    /// Split into the producer and consumer endpoint handles.
229	    ///
230	    /// - Consuming `self` makes each handle exist at most once
231	    ///   per ring per process; cross-process, one producing and
232	    ///   one consuming process is the SPSC contract.
233	    pub fn split(self) -> (Producer<'a>, Consumer<'a>) {
234	        (
235	            Producer::new(
236	                self.header,
237	                self.seqs,
238	                self.slots,
239	                self.slot_size,
240	                self.capacity,
241	                self.mask,
242	            ),
243	            Consumer::new(
244	                self.header,
245	                self.seqs,
246	                self.slots,
247	                self.slot_size,
248	                self.capacity,
249	                self.mask,
250	            ),
251	        )
252	    }
253	}
254	
255	/// Validate a region base pointer and cast it to the `Header`
256	/// it must start with; shared by [`Ring::init`] /
257	/// [`Ring::attach`].
258	///
259	/// - Same split of duties as v0's: alignment and header room
260	///   here, full-geometry length with the caller.
261	fn header_ptr(base: *mut u8, len: usize) -> Result<*const Header, Error> {
262	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
263	        return Err(Error::Misaligned);
264	    }
265	    if len < size_of::<Header>() {
266	        return Err(Error::TooSmall);
267	    }
268	    Ok(base as *const Header)
269	}
270	
271	/// Bytes from one seq word to the next.
272	///
273	/// - `size_of::<AtomicU32>()` packs the array, 16 seqs to a
274	///   cache line, which is the form the measurement rung ran.
275	/// - [`CACHE_LINE_SIZE`] gives every seq its own line. We
276	///   think the streaming loss to v0 is that both sides write
277	///   a seq word every message and 16 of them share a line, so
278	///   neighbouring slots false-share it; padding is the cheap
279	///   probe of that, and the in-slot seq the fix if it holds.
280	const SEQ_STRIDE: usize = size_of::<AtomicU32>();
281	
282	/// Bytes the seq array occupies, padded up to a cache line so
283	/// the slot array behind it stays line-aligned.
284	///
285	/// - u64: `capacity * SEQ_STRIDE` reaches `2^36` at the `2^30`
286	///   cap, which would wrap a 32-bit usize.
287	fn seq_bytes(capacity: u32) -> u64 {
288	    (capacity as u64 * SEQ_STRIDE as u64).next_multiple_of(CACHE_LINE_SIZE as u64)
289	}
290	
291	/// Byte offset of the slot array: header, then the padded seq
292	/// array.
293	///
294	/// - usize return: callers offset a pointer with it, and only
295	///   after the u64 region-size check has proven the region
296	///   fits in memory.
297	fn slots_offset(capacity: u32) -> usize {
298	    size_of::<Header>() + seq_bytes(capacity) as usize
299	}
300	
301	/// Bytes needed for a v1 region with the given geometry.
302	///
303	/// - Public: a pool that hands out ring segments sizes its
304	///   buffers by it.
305	/// - Computed in u64 for the same 32-bit wrap reason as v0's
306	///   `region_size`.
307	pub fn region_size(slot_size: u32, capacity: u32) -> u64 {
308	    size_of::<Header>() as u64 + seq_bytes(capacity) + slot_size as u64 * capacity as u64
309	}
310	
311	/// Geometry checks for [`Ring::init`] / [`Ring::attach`].
312	///
313	/// - Slot size as v0; capacity a power of two up to
314	///   [`MAX_CAPACITY`], 1 allowed.
315	fn validate_geometry(slot_size: u32, capacity: u32) -> Result<(), Error> {
316	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
317	        return Err(Error::BadSlotSize);
318	    }
319	    if capacity == 0 || !capacity.is_power_of_two() || capacity > MAX_CAPACITY {
320	        return Err(Error::BadCapacity);
321	    }
322	    Ok(())
323	}
