325	#[cfg(test)]
326	mod tests {
327	    use super::*;
328	    use crate::{Empty, Full};
329	    use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
330	
331	    /// Test message; two words so a torn write would be visible.
332	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
333	    #[repr(C)]
334	    struct Msg {
335	        seq: u64,
336	        val: u64,
337	    }
338	
339	    /// Test region: header + the seq array at its widest (16
340	    /// seqs × 1 line, so either [`SEQ_STRIDE`] fits) + 16
341	    /// slots × 1 line — enough for every capacity the tests use.
342	    const REGION_BYTES: usize =
343	        size_of::<Header>() + (16 * CACHE_LINE_SIZE) + (16 * CACHE_LINE_SIZE);
344	
345	    /// Cache-line-aligned backing store for the tests' rings.
346	    #[repr(C, align(64))]
347	    struct Region([u8; REGION_BYTES]);
348	
349	    impl Region {
350	        fn new() -> Self {
351	            Region([0; REGION_BYTES])
352	        }
353	    }
354	
355	    /// Fill `count` messages through `prod`, `seq = i`, `val = i
356	    /// * 10`, then assert Full.
357	    fn fill(prod: &mut Producer<'_>, count: u64) {
358	        for i in 0..count {
359	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
360	            slot.seq = i;
361	            slot.val = i * 10;
362	            slot.commit();
363	        }
364	        assert!(prod.reserve_slot_with::<Msg>(|_| false).is_err());
365	    }
366	
367	    /// Drain `count` messages through `cons` in order, then
368	    /// assert Empty.
369	    fn drain(cons: &mut Consumer<'_>, count: u64) {
370	        for i in 0..count {
371	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
372	            assert_eq!(
373	                *msg,
374	                Msg {
375	                    seq: i,
376	                    val: i * 10
377	                }
378	            );
379	            msg.release();
380	        }
381	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
382	    }
383	
384	    #[test]
385	    fn init_rejects_bad_geometry() {
386	        let mut r = Region::new();
387	        assert_eq!(
388	            Ring::init(&mut r.0, 63, 4).err().unwrap(),
389	            Error::BadSlotSize
390	        );
391	        assert_eq!(
392	            Ring::init(&mut r.0, 0, 4).err().unwrap(),
393	            Error::BadSlotSize
394	        );
395	        assert_eq!(
396	            Ring::init(&mut r.0, 64, 3).err().unwrap(),
397	            Error::BadCapacity
398	        );
399	        assert_eq!(
400	            Ring::init(&mut r.0, 64, 0).err().unwrap(),
401	            Error::BadCapacity
402	        );
403	        assert_eq!(
404	            Ring::init(&mut r.0, 64, 1 << 31).err().unwrap(),
405	            Error::BadCapacity
406	        );
407	        assert_eq!(Ring::init(&mut r.0, 64, 32).err().unwrap(), Error::TooSmall);
408	        assert_eq!(
409	            Ring::init(&mut r.0[1..], 64, 4).err().unwrap(),
410	            Error::Misaligned
411	        );
412	        // 32-bit tripwire: N * M wraps a 32-bit usize; the u64
413	        // region_size must still reject it.
414	        assert_eq!(
415	            Ring::init(&mut r.0, 1 << 26, 1 << 6).err().unwrap(),
416	            Error::TooSmall
417	        );
418	    }
419	
420	    #[test]
421	    fn region_size_pads_seqs_to_a_line() {
422	        // Whatever [`SEQ_STRIDE`] is, the seq array holds
423	        // `capacity` strided words and rounds up to a whole
424	        // line, so the slots behind it stay line-aligned.
425	        for capacity in [1u32, 4, 16, 32] {
426	            let want = capacity as u64 * SEQ_STRIDE as u64;
427	            let seqs =
428	                region_size(64, capacity) - size_of::<Header>() as u64 - 64 * capacity as u64;
429	            assert!((want..want + CACHE_LINE_SIZE as u64).contains(&seqs));
430	            assert!(seqs.is_multiple_of(CACHE_LINE_SIZE as u64));
431	            assert!(slots_offset(capacity).is_multiple_of(CACHE_LINE_SIZE));
432	        }
433	    }
