435	    #[test]
436	    fn attach_validates_header() {
437	        let mut r = Region::new();
438	        // Not initialized yet: magic is zero.
439	        let err = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
440	            .err()
441	            .unwrap();
442	        assert_eq!(err, Error::BadMagic);
443	        Ring::init(&mut r.0, 64, 4).unwrap();
444	        let ring = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }.unwrap();
445	        assert_eq!(ring.slot_size, 64);
446	        assert_eq!(ring.capacity, 4);
447	        assert_eq!(ring.mask, 3);
448	        // A region built with a different CACHE_LINE_SIZE
449	        // (simulated by editing the recorded value) is rejected.
450	        ring.header.cache_line_size.store(128, Ordering::Relaxed);
451	        let err = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
452	            .err()
453	            .unwrap();
454	        assert_eq!(err, Error::BadCacheLine);
455	    }
