457	    #[test]
458	    fn cross_kind_attach_fails_on_magic() {
459	        let mut r = Region::new();
460	        crate::spsc::v0::Ring::init(&mut r.0, 64, 4).unwrap();
461	        let err = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
462	            .err()
463	            .unwrap();
464	        assert_eq!(err, Error::BadMagic);
465	    }
