467	    #[test]
468	    fn attach_resumes_mid_stream() {
469	        // The header index lines are resume state: a second
470	        // attach after two commits and one release continues
471	        // where the first left off.
472	        let mut r = Region::new();
473	        {
474	            let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
475	            for i in 0..2u64 {
476	                let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
477	                slot.seq = i;
478	                slot.val = i * 10;
479	                slot.commit();
480	            }
481	            cons.reserve_slot_with::<Msg>(|_| false).unwrap().release();
482	        }
483	        let (mut prod, mut cons) = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
484	            .unwrap()
485	            .split();
486	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
487	        assert_eq!(msg.seq, 1);
488	        msg.release();
489	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
490	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
491	        slot.seq = 2;
492	        slot.commit();
493	        assert_eq!(cons.reserve_slot_with::<Msg>(|_| false).unwrap().seq, 2);
494	    }
