496	    #[test]
497	    fn user_words_zeroed_and_shared() {
498	        let mut r = Region::new();
499	        // Dirty the region so init's zeroing is observable.
500	        r.0.fill(0xAA);
501	        let ring = Ring::init(&mut r.0, 64, 4).unwrap();
502	        let (prod, mut cons) = ring.split();
503	        assert!(prod.user().iter().all(|w| w.load(Ordering::Relaxed) == 0));
504	        prod.user()[0].store(7, Ordering::Release);
505	        assert_eq!(cons.user()[0].load(Ordering::Acquire), 7);
506	        // The user line must not alias ring state: scribbling
507	        // all of it leaves the ring empty and functional.
508	        for w in cons.user().iter() {
509	            w.store(u32::MAX, Ordering::Relaxed);
510	        }
511	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
512	    }
