514	    #[test]
515	    fn indices_survive_u32_wrap() {
516	        let mut r = Region::new();
517	        let ring = Ring::init(&mut r.0, 64, 4).unwrap();
518	        // Simulate a long-running ring two commits shy of the
519	        // u32 wrap (empty state: p == c, every slot claimable
520	        // for the lap that starts at `start`).
521	        let start = u32::MAX - 1;
522	        ring.header.producer_idx.store(start, Ordering::Relaxed);
523	        ring.header.consumer_idx.store(start, Ordering::Relaxed);
524	        for i in 0..4u32 {
525	            let idx = start.wrapping_add(i);
526	            unsafe { &*ring.seqs.byte_add((idx & ring.mask) as usize * SEQ_STRIDE) }
527	                .store(idx, Ordering::Relaxed);
528	        }
529	        let (mut prod, mut cons) = ring.split();
530	        // Fill across the wrap: positions 2, 3, 0, 1.
531	        fill(&mut prod, 4);
532	        drain(&mut cons, 4);
533	    }
