535	    #[test]
536	    fn roundtrip_full_empty() {
537	        let mut r = Region::new();
538	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
539	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
540	        fill(&mut prod, 4);
541	        drain(&mut cons, 4);
542	        // One more write lands in the masked-around slot 0.
543	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
544	        slot.seq = 4;
545	        slot.commit();
546	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
547	        assert_eq!(msg.seq, 4);
548	        msg.release();
549	    }
