551	    #[test]
552	    fn capacity_one_alternates() {
553	        // M = 1: one seq word carries the whole state through
554	        // claimable, committed, and released, and the ring
555	        // alternates Full/Empty.
556	        let mut r = Region::new();
557	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 1).unwrap().split();
558	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
559	        for i in 0..5u64 {
560	            fill(&mut prod, 1);
561	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
562	            assert_eq!(msg.seq, 0);
563	            // Release lets the producer in again.
564	            msg.release();
565	            assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
566	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
567	            slot.seq = i + 100;
568	            slot.commit();
569	            assert!(prod.reserve_slot_with::<Msg>(|_| false).is_err());
570	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
571	            assert_eq!(msg.seq, i + 100);
572	            msg.release();
573	        }
574	    }
575	
576	    #[test]
577	    fn capacity_two_and_sixteen() {
578	        for cap in [2u32, 16] {
579	            let mut r = Region::new();
580	            let (mut prod, mut cons) = Ring::init(&mut r.0, 64, cap).unwrap().split();
581	            // Two full laps and a partial one.
582	            fill(&mut prod, cap as u64);
583	            drain(&mut cons, cap as u64);
584	            fill(&mut prod, cap as u64);
585	            drain(&mut cons, cap as u64);
586	            fill(&mut prod, cap as u64);
587	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
588	            assert_eq!(msg.seq, 0);
589	            msg.release();
590	            // One slot free again.
591	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
592	            slot.seq = cap as u64;
593	            slot.commit();
594	            assert!(prod.reserve_slot_with::<Msg>(|_| false).is_err());
595	        }
596	    }
597	
598	    #[test]
599	    // Dropping the guards is the behavior under test; they have
600	    // no Drop impl by design (abandon = do nothing).
601	    #[allow(clippy::drop_non_drop)]
602	    fn abandoned_guards_publish_nothing() {
603	        let mut r = Region::new();
604	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
605	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
606	        slot.seq = 99;
607	        drop(slot);
608	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
609	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
610	        slot.seq = 1;
611	        slot.commit();
612	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
613	        assert_eq!(msg.seq, 1);
614	        drop(msg);
615	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
616	        assert_eq!(msg.seq, 1);
617	        msg.release();
618	    }
619	
620	    #[test]
621	    fn reserve_slot_with_policy_counts_and_gives_up() {
622	        let mut r = Region::new();
623	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
624	        let mut seen = Vec::new();
625	        let err = cons
626	            .reserve_slot_with::<Msg>(|attempt| {
627	                seen.push(attempt);
628	                attempt < 2
629	            })
630	            .err()
631	            .unwrap();
632	        assert_eq!(err, Empty);
633	        assert_eq!(seen, [0, 1, 2]);
634	        fill(&mut prod, 4);
635	        let err = prod
636	            .reserve_slot_with::<Msg>(|attempt| attempt < 2)
637	            .err()
638	            .unwrap();
639	        assert_eq!(err, Full);
640	        let msg = cons
641	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with a message available"))
642	            .unwrap();
643	        assert_eq!(msg.seq, 0);
644	        msg.release();
645	        let mut slot = prod
646	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with room available"))
647	            .unwrap();
648	        slot.seq = 4;
649	        slot.commit();
650	    }
651	
652	    /// The two-thread stream at capacity `cap`, `count`
653	    /// messages, through `policy` on both ends.
654	    fn threaded(cap: u32, count: u64, policy: fn(u32) -> bool) {
655	        let mut r = Region::new();
656	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, cap).unwrap().split();
657	        std::thread::scope(|s| {
658	            s.spawn(move || {
659	                for i in 0..count {
660	                    let mut slot = prod.reserve_slot_with::<Msg>(policy).unwrap();
661	                    slot.seq = i;
662	                    slot.val = i * 3;
663	                    slot.commit();
664	                }
665	            });
666	            s.spawn(move || {
667	                for i in 0..count {
668	                    let msg = cons.reserve_slot_with::<Msg>(policy).unwrap();
669	                    assert_eq!(msg.seq, i);
670	                    assert_eq!(msg.val, i * 3);
671	                    msg.release();
672	                }
673	            });
674	        });
675	    }
676	
677	    #[test]
678	    fn threaded_spsc() {
679	        // Reduced under Miri: interpreted spin loops are slow,
680	        // and its scheduler explores interleavings at any count.
681	        const COUNT: u64 = if cfg!(miri) { 200 } else { 100_000 };
682	        for cap in [1u32, 2, 4, 16] {
683	            threaded(cap, COUNT, crate::policy::spin);
